    var GS4_N9_3 = { 'ガッツ': 'やる気・根性', '矢先': '何かをしようとするちょうどその時', '生い立ち': '成長過程', '買って出る': '自ら進んで引き受ける', '浮気': '不倫', '旅立つ': '亡くなる', '無性に': '抑えきれないさま・やたらに' };
