    // 全範囲 mistakes are logged separately ({ id: { answer, time } }) so they stay in the
    // mistake note even after a 全範囲 retry, without touching the 成績表.
    var allModeMistakes = loadJSON('jlptAllModeMistakes', {});
    // Temporary answers used while reviewing 全範囲 mistakes from the mistake note (not saved)
    var reviewAnswers = {};
    var answerMode = 'report'; // 'report' | 'all' | 'allMistakes' | 'practice' (review / weak-point practice from 統計)

    function setAnswerMode(mode) {
        if (mode === true) mode = 'all';
        if (mode === false || !mode) mode = 'report';
        answerMode = mode;
        userAnswers = (mode === 'all') ? allModeAnswers : (mode === 'allMistakes' || mode === 'practice') ? reviewAnswers : reportAnswers;
    }

    // ===== Statistics data =====
    // attemptLog: every answer ever given, in every mode: { id, b (blank index or -1), ok, t (time), ms (answer time), m (mode) }
    // dailyStats: { 'YYYY-MM-DD': { answered, correct } }  — a day counts as a study day only if answered > 0
    var MAX_ATTEMPTS = 6000;
    var attemptLog = loadJSON('jlptAttempts', []);
    if (!Array.isArray(attemptLog)) attemptLog = [];
    var dailyStats = loadJSON('jlptDaily', {});
    var dailyGoal = parseInt(localStorage.getItem('jlptDailyGoal'), 10) || 20;
    var questionShownAt = Date.now();

    function recordAttempt(q, blankIdx, isCorrect) {
        var now = Date.now();
        var ms = Math.max(0, Math.min(now - questionShownAt, 300000));
        var modeCode = { report: isBookmarkMode ? 'b' : 'r', all: 'a', allMistakes: 'x', practice: 'p' }[answerMode] || 'r';
        attemptLog.push({ id: q.id, b: blankIdx, ok: isCorrect ? 1 : 0, t: now, ms: ms, m: modeCode });
        if (attemptLog.length > MAX_ATTEMPTS) attemptLog.splice(0, attemptLog.length - MAX_ATTEMPTS);
        questionShownAt = now;
        var key = getTodayDateString();
        var day = dailyStats[key] || (dailyStats[key] = { answered: 0, correct: 0 });
        day.answered++;
        if (isCorrect) day.correct++;
        try {
            localStorage.setItem('jlptAttempts', JSON.stringify(attemptLog));
            localStorage.setItem('jlptDaily', JSON.stringify(dailyStats));
        } catch (e) { /* storage full: keep going with in-memory data */ }
    }
    // True whenever answers should NOT touch the 成績表, report mistake note or statistics
    function isAllModeActive() {
        return answerMode !== 'report';
    }
    function saveAnswers() {
        if (answerMode === 'all') localStorage.setItem('jlptAllModeAnswers', JSON.stringify(allModeAnswers));
        else if (answerMode === 'report') { localStorage.setItem('jlptUserAnswers', JSON.stringify(reportAnswers)); localStorage.setItem('jlptAnswerShadow', JSON.stringify(reportAnswers)); }
        // 'allMistakes' review answers are temporary
    }
    function saveAllModeMistakes() {
        localStorage.setItem('jlptAllModeMistakes', JSON.stringify(allModeMistakes));
    }

    // After any answer in 全範囲 (or while reviewing its mistakes): log it if it's wrong,
    // remove it from the log once the question is fully answered correctly.
    function updateAllModeMistakeLog(q) {
        if (answerMode !== 'all' && answerMode !== 'allMistakes') return;
        var orig = findQuestion(q.id);
        var a = userAnswers[q.id];
        if (typeof a !== 'string') return;
        var hasWrong = false, complete = true;
        if (orig.type === 'Text Grammar') {
            var parts = a.split('|');
            orig.blanks.forEach(function(blank, i) {
                if (!parts[i]) { complete = false; return; }
                if (parts[i] !== blank.options[blank.correct]) hasWrong = true;
            });
        } else if (orig.type === 'Composition') {
            hasWrong = !isCompositionAnswerCorrect(orig.id, a);
        } else {
            hasWrong = a !== orig.options[orig.correct];
        }
        if (hasWrong) allModeMistakes[q.id] = { answer: a, time: Date.now() };
        else if (complete) delete allModeMistakes[q.id];
        saveAllModeMistakes();
    }
    var progressData = loadJSON('jlptProgress', {});
    var resumeData = loadJSON('jlptResume', {});
    var shuffledOrders = loadJSON('jlptShuffledOrders', {});
    var timeSpent = loadJSON('jlptTimeSpent', {});
    var correctPerDay = loadJSON('jlptCorrectPerDay', {});
    var categoryStats = loadJSON('jlptCategoryStats', {});
    var bookmarkedQuestions = loadJSON('jlptBookmarks', []);
    var mistakeTimestamps = loadJSON('jlptMistakeTimestamps', {});
    var statsData = loadJSON('jlptStatsData', { total: 0, correct: 0 });
    var statsAnsweredFlags = loadJSON('jlptStatsAnsweredFlags', {});
    if (!Array.isArray(bookmarkedQuestions)) bookmarkedQuestions = [];

    var welcomeView = document.getElementById('welcome-view');
    var mainHeader = document.getElementById('main-header');
    var appLogo = document.getElementById('app-logo');
    var quizContainer = document.getElementById('quiz-container');
    var nextBtn = document.getElementById('next-btn');
    var quizFooter = document.getElementById('quiz-footer');
    var daySelector = document.getElementById('day-selector');
    var weekButtons = document.querySelectorAll('#week-selector button');
    var dayButtons = document.querySelectorAll('#day-selector button');
    var historyList = document.getElementById('history-list');
    var dashboardView = document.getElementById('dashboard-view');
    var statsView = document.getElementById('stats-view');
    var bookmarksView = document.getElementById('bookmarks-view');
    var mistakesView = document.getElementById('mistakes-view');
    var wordlistView = document.getElementById('wordlist-view');
    var settingsView = document.getElementById('settings-view');
