    var dashboardToggle = document.getElementById('dashboard-toggle');
    var statsToggle = document.getElementById('stats-toggle');
    var bookmarksToggle = document.getElementById('bookmarks-toggle');
    var mistakesToggle = document.getElementById('mistakes-toggle');
    var backToQuizBtnDash = document.getElementById('back-to-quiz-from-dash');
    var backToQuizBtnStats = document.getElementById('back-to-quiz-from-stats');
    var backToQuizBtnBookmarks = document.getElementById('back-to-quiz-from-bookmarks');
    var backToQuizBtnMistakes = document.getElementById('back-to-quiz-from-mistakes');
    var resetProgressBtn = document.getElementById('reset-progress');
    var resetAllDataBtn = document.getElementById('reset-all-data');
    var dashboardContent = document.getElementById('dashboard-content');
