    // 解答の解説 (設定 › 問題を解くとき) and the 解説リーダー (開発者メニュー): their rows are added here, next to the others
    (function addExplainRows() {
        var timer = document.getElementById('set-timer'), row = timer && timer.closest('.setting-row');
        if (row && !document.getElementById('set-explain')) {
            var r = document.createElement('div');
            r.className = 'setting-row';
            r.innerHTML = '<span>解答の解説</span><span class="seg" id="set-explain"><button data-v="on">表示</button><button data-v="off">非表示</button></span>';
            row.parentNode.insertBefore(r, row.nextSibling);
        }
        var hide = document.getElementById('dev-hide');
        if (hide && !document.getElementById('dev-explain')) {
            var d = document.createElement('div');
            d.className = 'setting-row wrap';
            d.innerHTML = '<span>解説リーダー</span><button id="dev-explain" class="dev-btn">解説を読む</button><div class="stat-sub rsgoal-note">読解以外のすべての問題を、解説と並べて読みます。教材・種類で絞り込み、番号で移動し、解説のない問題も探せます。</div>';
            hide.parentNode.insertBefore(d, hide);
        }
    })();

