    // 読む速さの目標: 0 = 標準 (the book's pace, but never slower than READ_GOAL_FLOOR), otherwise 字/分 chosen by the learner
    function refreshReadingGoalSetting() {
        var cpm = readingGoalCpm();
        markSeg('set-rsgoal', cpm ? 'custom' : 'book');
        document.getElementById('rsgoal-stepper').classList.toggle('off', !cpm);
        document.getElementById('set-rsgoal-value').textContent = cpm + '字/分';
        var rg = standardPaceRange();
        document.getElementById('rsgoal-note').textContent = cpm
            ? 'すべての本の内容理解で、1分に' + cpm + '字のペースを目標にします。'
            : 'すべての文章で最低' + READ_GOAL_FLOOR + '字/分（本番のJLPTの時間配分の目安）。本の目標解答時間のほうが速い日は、そのペースにします' + (rg ? '（いまは約' + rg[0] + (rg[1] !== rg[0] ? '〜' + rg[1] : '') + '字/分）' : '') + '。';
    }
    function setReadingGoal(cpm) {
        setSetting('readingGoal', cpm ? Math.max(READ_GOAL_MIN, Math.min(READ_GOAL_MAX, cpm)) : 0);
        refreshReadingGoalSetting();
    }
    document.querySelectorAll('#set-rsgoal button').forEach(function(b) {
        b.addEventListener('click', function() {
            if (b.dataset.v === 'book') return setReadingGoal(0);
            if (readingGoalCpm()) return;
            var rg = standardPaceRange();     // start from the standard pace so the switch feels continuous
            setReadingGoal(rg ? Math.round((rg[0] + rg[1]) / 2 / READ_GOAL_STEP) * READ_GOAL_STEP : 300);
        });
    });
    document.getElementById('set-rsgoal-minus').addEventListener('click', function() { setReadingGoal((readingGoalCpm() || 300) - READ_GOAL_STEP); });
    document.getElementById('set-rsgoal-plus').addEventListener('click', function() { setReadingGoal((readingGoalCpm() || 300) + READ_GOAL_STEP); });

