        // い-adjectives (分かった is a verb, 高かった an adjective)
        if ((m = s.match(/^(.+)(?:かった|くて|くない|くなかった|ければ|くなる|くなった|くなって)$/))) add(m[1] + 'い', KARU_VERBS.indexOf(m[1].replace(/か$/, '') + 'かる') !== -1 ? 1 : 0);
        if ((m = s.match(/^(.+)かった$/)) && KARU_VERBS.indexOf(m[1] + 'かる') !== -1) add(m[1] + 'かる', 0);
