    function myWords() { return activeDeck ? (myWordList || []) : wordList; }
    function deckById(id) { return WORD_DECKS.filter(function(d) { return d.id === id; })[0] || null; }
    function deckStoreKey(id) { return 'jlptDeck_' + id; }
    function loadDeckWords(d) {
        var saved = loadJSON(deckStoreKey(d.id), []), byId = {};
        if (Array.isArray(saved)) saved.forEach(function(e) { if (e && e.id) byId[e.id] = e; });
        return d.words.map(function(w) { return byId[w.id] ? Object.assign(JSON.parse(JSON.stringify(w)), byId[w.id], { context: w.context, ctxTr: w.ctxTr, others: w.others, source: w.source, deckDay: w.deckDay }) : JSON.parse(JSON.stringify(w)); });
    }
    function switchDeck(id) {
        id = id || null;
        if (id === activeDeck) return;
        if (!activeDeck) myWordList = wordList;
        var d = id ? deckById(id) : null;
        wordList = d ? loadDeckWords(d) : (myWordList || wordList);
        activeDeck = d ? id : null;
        if (!activeDeck) myWordList = null;
        wordUndo = []; wordRedo = []; if (typeof updateWordUndoUi === 'function') updateWordUndoUi();
        wlWeek = ''; buildWordListWeekOptions();
        renderDeckPicker();
    }
    function deckBookPanel() {
        var d = activeDeck ? deckById(activeDeck) : null; if (!d || !d.book) return '';
        var bk = d.book, cnt = {}, done = 0;
        d.words.forEach(function(w) { cnt[w.deckDay] = (cnt[w.deckDay] || 0) + 1; });
        var cells = bk.schedule.map(function(sc, i) {
            var n = cnt[i + 1] || 0; if (n) done++;
            return '<button class="wl-sd' + (n ? '' : ' empty') + (String(i + 1) === String(wlWeek) ? ' on' : '') + '"' + (n ? ' data-day="' + (i + 1) + '"' : ' disabled') + ' title="' + escapeHtml(sc.pos + ' p.' + sc.pages) + '">' +
                '<div class="d">' + (i + 1) + '일째</div><div class="p">' + escapeHtml(sc.pos) + '</div><div class="p">p.' + escapeHtml(sc.pages) + '</div>' + (n ? '<div class="c">' + n + '語</div>' : '') + '</button>';
        }).join('');
        var closed = getSetting('wlBookClosed', false);
        return '<div class="wl-book' + (closed ? ' closed' : '') + '"><div class="wl-book-head"><img src="' + bk.cover + '" alt="">' +
            '<div><div class="wl-book-t">' + escapeHtml(d.title.replace(/ N1$/, '')) + '<b>N1</b></div>' +
            '<div class="wl-book-m">' + escapeHtml(bk.author + ' 지음 · ' + bk.publisher + ' · ' + bk.year) + '</div>' +
            '<div class="wl-book-m">학습 스케줄 ' + done + ' / ' + bk.schedule.length + '일째 수록 · ' + d.words.length + '語</div>' +
            '<div class="wl-book-bar"><i style="width:' + Math.round(done / bk.schedule.length * 100) + '%"></i></div></div>' +
            '<button class="wl-book-tg">' + (closed ? 'スケジュール ▾' : '閉じる ▴') + '</button></div>' +
            '<div class="wl-sched">' + cells + '</div></div>';
    }
    function renderDeckPicker() {
        var box = document.getElementById('wl-decks'); if (!box) return;
        var mine = activeDeck ? (myWordList || []).length : wordList.length;
        box.innerHTML = '<div class="wl-modes-label">単語帳を選ぶ</div><div class="wl-deck-row">' +
            '<button class="wl-deck' + (activeDeck ? '' : ' on') + '" data-deck=""><span class="wl-deck-t">マイ単語帳</span><span class="wl-deck-n">' + mine + '語</span></button>' +
            WORD_DECKS.map(function(d) {
                var cv = d.book && d.book.cover ? '<img class="wl-deck-cover" src="' + d.book.cover + '" alt="">' : '';
                return '<button class="wl-deck curated' + (cv ? ' has-cover' : '') + (activeDeck === d.id ? ' on' : '') + '" data-deck="' + d.id + '">' + cv + '<span class="wl-deck-txt"><span class="wl-deck-t">' + escapeHtml(d.title) + '</span><span class="wl-deck-n">' + escapeHtml(d.sub) + '・' + d.words.length + '語</span></span></button>';
            }).join('') + '</div>' + deckBookPanel();
        box.querySelectorAll('.wl-deck').forEach(function(b) { b.addEventListener('click', function() { switchDeck(b.dataset.deck); renderWordListItems(); }); });
        box.querySelectorAll('.wl-sd[data-day]').forEach(function(b) { b.addEventListener('click', function() {
            var sel = document.getElementById('wordlist-week'), v = wlWeek === b.dataset.day ? '' : b.dataset.day;
            sel.value = v; wlWeek = v; renderWordListItems(); renderDeckPicker();
        }); });
        var tg = box.querySelector('.wl-book-tg'); if (tg) tg.addEventListener('click', function() { setSetting('wlBookClosed', !getSetting('wlBookClosed', false)); renderDeckPicker(); });
        document.getElementById('wordlist-view').classList.toggle('deck-on', !!activeDeck);
        var nb = document.querySelector('#wordlist-sort-controls button[data-sort="new"]'); if (nb) nb.textContent = activeDeck ? '本の順' : '新しい順';
    }
    function wordSnap() { var m = {}; wordList.forEach(function(e, i) { m[e.id] = { j: JSON.stringify(e), i: i }; }); return m; }
    function wordBegin() { return wordSnap(); }
    function wordCommit(before, label) {
        var after = wordSnap(), ch = {}, any = false;
        Object.keys(before).concat(Object.keys(after)).forEach(function(id) {
            var b = before[id] || null, a = after[id] || null;
            if ((b && b.j) !== (a && a.j) && !ch[id]) { ch[id] = { b: b, a: a }; any = true; }
        });
        if (!any) return;
        wordUndo.push({ label: label, ch: ch });
        if (wordUndo.length > 50) wordUndo.shift();
        wordRedo = [];
        updateWordUndoUi();
    }
    function wordApply(ch, side) {
        Object.keys(ch).forEach(function(id) {
            var st = ch[id][side], idx = wordList.findIndex(function(e) { return e.id === id; });
            if (!st) { if (idx >= 0) wordList.splice(idx, 1); return; }
            var obj = JSON.parse(st.j), other = ch[id][side === 'a' ? 'b' : 'a'];
            if (idx < 0) { wordList.splice(Math.min(st.i, wordList.length), 0, obj); return; }
            if (!other) { wordList[idx] = obj; return; }
            // a card the step edited: put back only the fields the step changed (a review since then stays)
            var from = JSON.parse(other.j), cur = wordList[idx];
            Object.keys(obj).concat(Object.keys(from)).forEach(function(k) {
                if (JSON.stringify(obj[k]) === JSON.stringify(from[k])) return;
                if (obj[k] === undefined) delete cur[k]; else cur[k] = obj[k];
            });
        });
        saveWordList();
        if (wordlistView.style.display !== 'none') renderWordListItems();
        updateWordUndoUi();
    }
    function wordUndoStep() {
        var act = wordUndo.pop(); if (!act) return;
        wordApply(act.ch, 'b'); wordRedo.push(act); updateWordUndoUi();
        showToast('元に戻しました：' + act.label);
    }
    function wordRedoStep() {
        var act = wordRedo.pop(); if (!act) return;
        wordApply(act.ch, 'a'); wordUndo.push(act); updateWordUndoUi();
        showToast('やり直しました：' + act.label);
    }
    function updateWordUndoUi() {
        var u = document.getElementById('wordlist-undo'), r = document.getElementById('wordlist-redo');
        if (u) { u.disabled = !wordUndo.length; u.title = wordUndo.length ? '元に戻す：' + wordUndo[wordUndo.length - 1].label : '元に戻す'; }
        if (r) { r.disabled = !wordRedo.length; r.title = wordRedo.length ? 'やり直す：' + wordRedo[wordRedo.length - 1].label : 'やり直す'; }
    }

    // A badge's description fades after 3 seconds, or right away when you tap somewhere else
    var badgeTipFor = null;
    function hideBadgeTip() {
        if (!badgeTipFor) return;
        badgeTipFor = null;
        clearTimeout(window.toastTimeout);
        document.getElementById('app-toast').classList.remove('show');
    }
    document.addEventListener('click', function(e) { if (badgeTipFor && !e.target.closest('.badge')) hideBadgeTip(); }, true);
    window.addEventListener('scroll', function() { if (badgeTipFor) hideBadgeTip(); }, { passive: true });
    function showToast(msg, ms) {
        badgeTipFor = null;
        var t = document.getElementById('app-toast');
        t.textContent = msg;
        t.classList.add('show');
        clearTimeout(window.toastTimeout);
        window.toastTimeout = setTimeout(function() { t.classList.remove('show'); }, ms || 2200);
    }

    // Text of a block without furigana and answer numbers, plus the text nodes that make it up
    function collectText(block) {
        var walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT, {
            acceptNode: function(n) {
                return n.parentElement && n.parentElement.closest('rt, rp, .option-prefix, .blank-number, .kw-blank i, .ar-title, .ar-author, .ar-h-title, .ar-h-author, .ar-pgbadge') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
            }
        });
        var parts = [], text = '', n;
        while ((n = walker.nextNode())) { parts.push({ node: n, start: text.length }); text += n.data; }
        return { text: text, parts: parts };
    }

    // Index (in collectText's text) of the character under the point, or the nearest one within 20px, or -1
    function charIndexAtPoint(collected, x, y, anyDistance) {
        var range = document.createRange();
        var best = -1, bestDist = anyDistance ? Infinity : 900;   // otherwise within 30px
        for (var p = 0; p < collected.parts.length; p++) {
            var part = collected.parts[p];
            if (!anyDistance && collected.parts.length > 20) {      // long texts (the reader): skip lines nowhere near the finger
                range.selectNodeContents(part.node);
                var nb = range.getBoundingClientRect();
                if (x < nb.left - 40 || x > nb.right + 40 || y < nb.top - 40 || y > nb.bottom + 40) continue;
            }
            for (var i = 0; i < part.node.data.length; i++) {
                range.setStart(part.node, i);
                range.setEnd(part.node, i + 1);
                var rects = range.getClientRects();
                for (var r = 0; r < rects.length; r++) {
                    var rc = rects[r];
                    if (x >= rc.left && x <= rc.right && y >= rc.top && y <= rc.bottom) return part.start + i;
                    var dx = Math.max(rc.left - x, 0, x - rc.right), dy = Math.max(rc.top - y, 0, y - rc.bottom);
                    var d = dx * dx + dy * dy;
                    if (d < bestDist) { bestDist = d; best = part.start + i; }
                }
            }
        }
        return best;
    }

    function charKind(ch) {
        if (/[一-鿿々〆ヶ]/.test(ch)) return 'kanji';
        if (/[゠-ヿｦ-ﾟ]/.test(ch)) return 'kata';
        if (/[぀-ゟ]/.test(ch)) return 'hira';
        if (/[A-Za-z0-9０-９Ａ-Ｚａ-ｚ]/.test(ch)) return 'latin';
        return 'other';
    }

    // Word boundaries around index: Intl.Segmenter when available, otherwise runs of the same script
    function wordBoundsAt(text, idx) {
        if (idx < 0 || idx >= text.length || charKind(text[idx]) === 'other') return null;
        if (window.Intl && Intl.Segmenter) {
            try {
                var segs = Array.from(new Intl.Segmenter('ja', { granularity: 'word' }).segment(text));
                for (var i = 0; i < segs.length; i++) {
                    var sg = segs[i];
                    if (idx >= sg.index && idx < sg.index + sg.segment.length) {
                        if (sg.isWordLike === false) return null;
                        return { start: sg.index, end: sg.index + sg.segment.length };
                    }
                }
            } catch (e) { /* fall through to the simple rule */ }
        }
        var kind = charKind(text[idx]), start = idx, end = idx + 1;
        while (start > 0 && charKind(text[start - 1]) === kind) start--;
        while (end < text.length && charKind(text[end]) === kind) end++;
        // a kanji word usually keeps a little okurigana (e.g. 慎重, 懐く)
        if (kind === 'kanji') { var k = 0; while (end < text.length && k < 2 && charKind(text[end]) === 'hira') { end++; k++; } }
        return { start: start, end: end };
    }

    function contextAround(text, start, end) {
        var a = start, b = end;
        while (a > 0 && !/[。！？\n]/.test(text[a - 1])) a--;
        while (b < text.length && !/[。！？\n]/.test(text[b])) b++;
        if (b < text.length) b++;
        var ctx = text.slice(a, b).trim();
        if (ctx.length > 120) {
            var s0 = Math.max(0, start - a - 50);
            ctx = (s0 > 0 ? '…' : '') + ctx.slice(s0, s0 + 110) + '…';
        }
        return ctx;
    }

    function escapeHtml(t) {
        return String(t).replace(/[&<>"]/g, function(c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; });
    }

    function highlightIn(context, word) {
        var safe = escapeHtml(context);
        if (!word) return safe;
        var w = escapeHtml(word);
        var i = safe.indexOf(w);
        return i === -1 ? safe : safe.slice(0, i) + '<mark class="word-mark">' + w + '</mark>' + safe.slice(i + w.length);
    }

    function currentQuestionId() {
        return (currentQuestions.length && quizView.style.display !== 'none' && currentQuestions[currentIndex]) ? currentQuestions[currentIndex].id : null;
    }

    function findWordEntry(word) {
        var k = normWord(word);
        return wordList.find(function(e) { return normWord(e.word) === k; });
    }

    function lookUpMeaning(word) {
        var qid = wordSheetState && (wordSheetState.qid || null);
        var q = qid ? findQuestion(qid) : null;
        if (q && q.notes) {
            for (var k in q.notes) if (k === word || k.replace(/[なするだ]$/, '') === word) return q.notes[k];
        }
        return wordDefinitions[word] ? wordDefinitions[word].jp : '';
    }

    function renderWordSheet() {
        var st = wordSheetState;
        var input = document.getElementById('word-sheet-word');
        if (st.text) input.value = st.text.slice(st.start, st.end);
        var word = sheetWordAndReading().word;
        var existing = !st.editId && findWordEntry(word);
        document.getElementById('word-sheet-title').textContent = st.editId ? '単語を編集' : (existing ? '単語帳に登録済み' : '単語帳に追加');
        // Editing from the 単語帳 saves by itself when the sheet closes: one 閉じる button, no キャンセル
        document.getElementById('word-sheet-save').textContent = st.editId ? '閉じる' : (existing ? '更新する' : '単語帳に追加');
        document.getElementById('word-sheet-cancel').hidden = !!st.editId;
        document.getElementById('word-sheet-autosave').hidden = !st.editId;
        document.getElementById('word-sheet-context').innerHTML = st.context ? '例文：' + highlightIn(st.context, word) : '';
        wsReadingRender();
        ['word-grow-left', 'word-trim-left', 'word-trim-right', 'word-grow-right'].forEach(function(id) {
            document.getElementById(id).style.display = st.text ? '' : 'none';
        });
    }

    // Desktop-site mode on a phone shows the page shrunk (e.g. 40%). Show the sheet at normal phone size over what you're
    // looking at, so the browser doesn't zoom in on its small text box (and lose your place).
    function wsFitToScreen(sheet) {
        var vv = window.visualViewport, sc = vv ? vv.scale : 1;
        if (!vv || sc > 0.85) { sheet.style.scale = ''; sheet.style.width = ''; sheet.style.left = ''; sheet.style.bottom = ''; return; }
        var z = Math.min(1 / sc, 3);
        sheet.style.transformOrigin = 'left bottom';
        sheet.style.scale = z;
        sheet.style.width = (vv.width / z) + 'px';
        sheet.style.left = vv.offsetLeft + 'px';
        sheet.style.bottom = Math.max(0, window.innerHeight - vv.offsetTop - vv.height) + 'px';
    }
    // remember where the reader / page was, and go back there when the sheet closes
    function wsSavePlace() {
        var body = document.querySelector('#ar-view.active .ar-body'), book = body && body.querySelector('.ar-book');
        return { x: window.scrollX, y: window.scrollY, body: body, bodyTop: body ? body.scrollTop : 0, book: book, bookLeft: book ? book.scrollLeft : 0 };
    }
    function wsRestorePlace(pl) {
        if (!pl) return;
        var go = function() {
            window.scrollTo(pl.x, pl.y);
            if (pl.body && pl.body.isConnected) pl.body.scrollTop = pl.bodyTop;
            if (pl.book && pl.book.isConnected) pl.book.scrollLeft = pl.bookLeft;
        };
        go(); requestAnimationFrame(go); setTimeout(go, 350);      // again after the keyboard has gone away
    }
    function openWordSheet(state) {
        state.place = wsSavePlace();
        wsFitToScreen(document.getElementById('word-sheet'));
        wordSheetState = state;
        var word = state.text ? state.text.slice(state.start, state.end) : state.word;
        var br = !state.text && parseBracketFurigana(word);
        if (br) { state.furiSrc = br.source; state.readingOrig = br.reading; word = br.word; }
        state.plainOrig = word; state.readingEdited = false;
        var ent0 = state.editId ? wordList.find(function(e) { return e.id === state.editId; }) : null;
        var rdBox = document.getElementById('word-sheet-reading');
        rdBox.value = br ? toHiragana(br.reading) : (ent0 && ent0.reading) || localReading(word) || '';
        if (!br && ent0 && ent0.reading) state.readingOrig = ent0.reading;
        rdBox.hidden = true; document.getElementById('ws-reading-edit').hidden = false;
        document.getElementById('word-sheet-word').value = word;
        var existing = state.editId ? wordList.find(function(e) { return e.id === state.editId; }) : findWordEntry(word);
        var meaningEl = document.getElementById('word-sheet-meaning');
        meaningEl.value = existing && existing.meaning ? existing.meaning : lookUpMeaning(word);
        if (!existing) {
            var plain = (parseBracketFurigana(word) || { word: word }).word, dForm = dictionaryForm(plain);
            if (dForm) meaningEl.value = dForm.form + '\n' + (meaningEl.value || lookUpMeaning(dForm.form));
            meaningEl.value = meaningEl.value.replace(/\n$/, '');
        }
        delete meaningEl.dataset.edited;
        document.getElementById('word-sheet-def').value = existing && existing.writeDef ? existing.writeDef : '';
        renderWordSheet();
        state.origInput = document.getElementById('word-sheet-word').value;
        state.origReading = document.getElementById('word-sheet-reading').value;
        state.origMeaning = meaningEl.value;
        state.origDef = document.getElementById('word-sheet-def').value;
        definitionPopup.classList.remove('active');
        blankPopup.classList.remove('active');
        document.getElementById('app-toast').classList.remove('show');   // don't cover the sheet's buttons
        document.getElementById('word-sheet').classList.add('active');
        document.getElementById('word-sheet-dim').classList.add('active');
    }

    // ---------- Your own furigana: 痴[ち]人[じん]の愛[あい] ----------
    // The kana in [ ] belongs to the kanji just before it (or, if there are none, to the text since the last ] or space).
    function parseBracketFurigana(src) {
        src = String(src || '').trim();
        if (!/\[[^\]]*\]/.test(src)) return null;
        var segs = [], buf = '', i = 0;
        while (i < src.length) {
            var c = src[i];
            if (c === '[') {
                var close = src.indexOf(']', i);
                if (close === -1) { buf += src.slice(i); break; }
                var rt = src.slice(i + 1, close).trim();
                var k = buf.length;
                while (k > 0 && hasKanji(buf[k - 1])) k--;
                if (k === buf.length) k = 0;                     // no kanji right before: use the whole run
                if (k > 0) segs.push({ text: buf.slice(0, k) });
                if (buf.slice(k)) segs.push(rt ? { base: buf.slice(k), rt: rt } : { text: buf.slice(k) });
                buf = ''; i = close + 1;
            } else if (c === ' ' || c === '　') {
                if (buf) segs.push({ text: buf });
                buf = ''; i++;
            } else { buf += c; i++; }
        }
        if (buf) segs.push({ text: buf });
        var word = segs.map(function(s) { return s.base || s.text; }).join('');
        var reading = segs.map(function(s) { return s.rt || s.text; }).join('');
        var source = segs.map(function(s) { return s.base ? s.base + '[' + s.rt + ']' : s.text; }).join('');
        return word ? { word: word, reading: reading, source: source, segs: segs } : null;
    }
    function bracketFuriganaHtml(spec) {
        var p = typeof spec === 'string' ? parseBracketFurigana(spec) : spec;
        if (!p) return escapeHtml(spec || '');
        return p.segs.map(function(s) {
            if (!s.base) return escapeHtml(s.text);
            var sp = Array.from(s.base).length > 1 ? rubySplitFor(s.base, s.rt) : null;          // 実社会[じっしゃかい] → 実(じっ)社(しゃ)会(かい)
            return '<ruby>' + (sp ? sp.map(function(x) { return escapeHtml(x[0]) + '<rt>' + escapeHtml(x[1]) + '</rt>'; }).join('') : escapeHtml(s.base) + '<rt>' + escapeHtml(s.rt) + '</rt>') + '</ruby>';
        }).join('');
    }
    // ---------- furigana per kanji ----------
    // Every reading the app has seen over a single kanji (the questions' ruby, the reading books' furigana, the
    // 単語帳's own [ ] furigana) is collected; a word's reading is then split so that each kanji gets one of its
