            3: { word: '藉くによしない', text: '藉くすべがない。藉きようがない。' },
            4: { word: 'しろがねの', text: '銀色の、雪におおわれた形容。' },
            5: { word: '衾の岡辺', text: '夜具をかぶったように、やわらかにふっくらとした岡のほとり。' },
            6: { word: '野に満つる香', text: '野原にたちこめる草の香。' },
